            QuestionData("සිංහල - භාෂාව", "හල් කිරීමේ ලකුණ හඳුන්වන්නේ කුමක් ලෙසද?", listOf("අල් ලකුණ", "පිල්ලම", "කොමාව", "තිත"), 0, "ව්‍යංජන අකුරක ස්වරය ඉවත් කිරීමට අල් ලකුණ යොදයි."),
            QuestionData("සිංහල - ව්‍යාකරණ", "ප්‍රථම පුරුෂ ඒක වචන නාම පදයක් වන්නේ,", listOf("ඔහු", "මම", "අපි", "ඔවුහු"), 0, "තමන් හෝ ඉදිරියේ සිටින අය නොවන වෙනත් අයෙකු පෙන්වීමයි."),
            QuestionData("සිංහල - භාෂාව", "සිංහල අකුරුවල ඇති 'පිල්ලම්' වර්ගයක් නොවන්නේ,", listOf("අල් ලකුණ", "ඉස්පිල්ල", "පාපිල්ල", "නැවතීමේ තිත"), 0, "නැවතීමේ තිත විරාම ලකුණකි. පිල්ලමක් නොවේ."),
            QuestionData("සිංහල - සාහිත්‍යය", "කුමාරතුංග මුණිදාසයන් විසින් රචිත ළමා කථාව කුමක්ද?", listOf("හීන්සැරය", "මඩොල් දූව", "ගම්පෙරළිය", "විරාගය"), 0, "හීන්සැරය, හත්පණ, මගුල් කෑම ඔහු ලියූ ළමා කථා වේ."),
            QuestionData("සිංහල - භාෂාව", "ගුණාත්මක අගයක් පෙන්වන වචන හඳුන්වන්නේ,", listOf("විශේෂණ", "නාම පද", "ක්‍රියා පද", "නිපාත"), 0, "ලස්සන, උස, හොඳ වැනි පද නාම විශේෂණ වේ.")
        )

        val idx = (q - 1).coerceIn(0, 59)
        val baseData = questions[idx]
        val finalTitle = "[$yearStr O/L - Q$q] " + baseData.text

        return QuestionData(baseData.topic, finalTitle, baseData.options, baseData.correctIdx, baseData.explanation)
    }
}
